import {createTask,updateProfile,addMaterial,saveReport,selectIdea,reportStale,exportTask,exportCandidate,markdownReport,copy} from './domain.js';
import {listTasks,persistTask} from './storage.js';
import {makeDemo} from './demo.js';
const app=document.querySelector('#app'),state={tasks:[],task:null,tab:'materials',reportId:null,editing:false,draft:null,storageError:'',drafts:new Map()};
let blobs=[],timer,busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+({plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',file:'<path d="M14 3H5v18h14V8l-5-5Z"/><path d="M14 3v5h5M8 12h8M8 16h5"/>',check:'<path d="m5 12 4 4L19 6"/>',box:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h8M8 17h4"/>',out:'<path d="M14 4h6v6m0-6-9 9M10 4H4v16h16v-6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M5 17v4h14v-4"/>'}[name]||'')+'</svg>';
function toast(text,error=false){const el=document.querySelector('#notice');el.textContent=text;el.className='toast'+(error?' error':'');el.hidden=false;clearTimeout(timer);timer=setTimeout(()=>el.hidden=true,error?9000:3500);}
function fileUrl(blob){const url=URL.createObjectURL(blob);blobs.push(url);return url;}
function route(){rememberDraft();let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{id='';}state.task=id==='sample'?state.tasks.find(t=>t.id==='sample-xilo-v1')||makeDemo():state.tasks.find(t=>t.id===id)||null;state.tab=id==='sample'?'report':'materials';state.reportId=null;state.editing=false;state.draft=null;render();window.scrollTo({top:0,behavior:'instant'});}
function navigate(id=''){if(location.hash==='#'+id||(!location.hash&&!id))route();else location.hash=id;}
function currentReport(){return state.task?.reports.find(r=>r.id===state.reportId)||state.task?.reports.at(-1);}
async function store(task){const saved=await persistTask(task);state.tasks=[saved,...state.tasks.filter(t=>t.id!==saved.id)];state.task=saved;}
function profileFields(p={}){return '<div class="field full"><label for="direction">我想做什么账号</label><textarea id="direction" name="direction" required maxlength="600" placeholder="例如：分享怎样用 AI 完成真实工作，帮助有想法的人做出自己的作品。">'+esc(p.direction)+'</textarea></div><div class="field"><label for="skills">我擅长什么 <span class="optional">选填</span></label><input id="skills" name="skills" maxlength="400" value="'+esc(p.skills)+'" placeholder="例如：软件开发、设计、门店经营"></div><div class="field"><label for="audience">希望谁关注我 <span class="optional">选填</span></label><input id="audience" name="audience" maxlength="400" value="'+esc(p.audience)+'" placeholder="不确定也可以，后续继续调整"></div>';}
function newPage(){
return '<section class="home-heading"><div><div class="eyebrow"><span class="accent-dot"></span> 你的创作，从一次好研究开始</div><h1 class="page-title">拆解好账号，<br>做出<span>自己的内容。</span></h1><p class="subtitle">从定位、选题到表达，找到值得借鉴的部分。</p></div><span class="edition">RESEARCH STUDIO<br><b>01 / 对标账号拆解</b></span></section>'+
'<div class="start-layout"><section class="panel start-panel"><div class="panel-title"><div><h2>从一个对标账号开始</h2><p class="muted">填入链接和方向，建立你的研究空间。</p></div><span class="round-icon">'+icon('search')+'</span></div>'+
'<form id="new-task"><div class="field"><label for="url">对标账号主页 <span class="platform-chip">抖音</span></label><div class="input-icon">'+icon('out')+'<input id="url" name="url" type="url" required placeholder="粘贴抖音主页或分享链接" maxlength="1500"></div></div>'+
'<div class="field direction-field"><label for="direction">你想做什么账号？</label><textarea id="direction" name="direction" required maxlength="600" placeholder="例如：分享怎样用 AI 完成真实工作，帮助有想法的人做出自己的作品。"></textarea></div>'+
'<details class="optional-fields"><summary><span>'+icon('plus')+' 补充我的背景 <small>选填，让建议更贴近你</small></span><span class="expand-mark">⌄</span></summary><div class="form-grid"><div class="field full"><label for="title">给这次研究起个名字</label><input id="title" name="title" maxlength="80" placeholder="例如：AI 实战类账号研究"></div><div class="field"><label for="skills">我擅长什么</label><input id="skills" name="skills" maxlength="400" placeholder="开发、设计、门店经营…"></div><div class="field"><label for="audience">希望谁关注我</label><input id="audience" name="audience" maxlength="400" placeholder="不确定也可以"></div></div></details>'+
'<div class="start-actions"><button class="btn primary" type="submit">建立研究任务 '+icon('arrow')+'</button><span class="local-hint">'+icon('box')+' 保存在当前浏览器</span></div><p class="capability-note">当前可保存链接与素材，自动读取及 AI 分析尚未接通。</p></form></section>'+
'<aside class="sample-preview"><div class="sample-topline"><span class="tiny-label">先看看完成后的样子</span><span class="badge sample">历史样例</span></div><div class="preview-canvas" aria-label="历史样例示意"><div class="preview-account"><span class="sample-avatar">X</span><div><strong>Xilo今天Ai了吗</strong><small>AI 创作 / 实战教程</small></div><span class="mini-symbol">↗</span></div><div class="preview-posters" aria-hidden="true"><div class="poster poster-one"><small>选题观察</small><strong>AI 视频<br>怎样做？</strong><span class="poster-play">▷</span><i>从任务到产物</i></div><div class="poster poster-two"><small>视觉观察</small><strong>让封面<br>有系列感</strong><span class="poster-shapes"><i></i><i></i><i></i></span><i>固定人物与配色</i></div><div class="poster poster-three"><small>工作流观察</small><strong>重复的事<br>交给 AI</strong><span class="poster-flow">① → ②</span><i>保留实际步骤</i></div></div><p class="preview-caption">题材示意，非原博主作品封面</p><div class="preview-finding"><span class="finding-icon">'+icon('check')+'</span><div><small>视觉表达 · 观察记录</small><p>固定人物、重复配色，<br>让不同选题保持系列感。</p></div></div></div>'+
'<div class="sample-bottom"><p>一份报告，连接观察与下一条选题。</p><button class="btn sample-button" data-action="sample">查看完整拆解 '+icon('arrow')+'</button><small>历史研究摘要，非实时分析</small></div></aside></div>'+
'<ol class="journey"><li><span>01</span><div><strong>收集真实材料</strong><p>主页、作品、你的观察</p></div></li><li><span>02</span><div><strong>看懂账号做法</strong><p>定位、选题、表达与依据</p></div></li><li><span>03</span><div><strong>留下候选选题</strong><p>结合你的方向，再决定做什么</p></div></li></ol>';
}
function taskPage(){const t=state.task,sample=t.mode==='sample';return '<div class="task-heading"><div><span class="badge '+(sample?'sample':'')+'">'+(sample?'历史样例 · 只读预览':'研究任务 · 本地保存')+'</span><h1>'+esc(t.title)+'</h1><a href="'+esc(t.url)+'" target="_blank" rel="noopener noreferrer">查看抖音主页 '+icon('out')+'</a></div><div class="button-row">'+(sample?'<button class="btn primary" data-action="new">研究自己的对标 '+icon('arrow')+'</button>':'')+'<button class="btn" data-action="export-json">'+icon('download')+' 导出研究</button></div></div>'+(sample?'<div class="notice-box">这是根据历史研究摘要整理的样例。原始证据包尚未完整归档，也未重新获取实时数据；它不会作为你提交其他链接后的分析结果。</div>':'<div class="notice-box neutral">链接和材料可真实保存。自动获取、视频转录及 AI 分析尚未接通，你可以先补充材料，再人工整理拆解报告。</div>')+'<details class="profile-summary"><summary><span><strong>我的方向</strong>　'+esc(t.profile.direction)+'</span><span class="muted">'+(sample?'查看背景':'编辑背景')+' ＋</span></summary>'+(sample?'<p class="muted">能力：'+esc(t.profile.skills)+'<br>受众：'+esc(t.profile.audience)+'<br>此背景仅属于样例。</p>':'<form id="profile"><div class="form-grid">'+profileFields(t.profile)+'</div><div class="form-actions"><span class="muted">修改后，旧报告会保留原背景并标记待更新。</span><button class="btn primary small" type="submit">保存背景</button></div></form>')+'</details><nav class="tabs" aria-label="研究步骤">'+[['materials','研究材料',t.materials.length],['report','拆解报告',t.reports.length],['cards','候选内容卡',t.cards.length]].map(([id,label,count],index)=>'<button aria-pressed="'+(state.tab===id)+'" class="tab '+(state.tab===id?'active':'')+'" data-action="tab" data-tab="'+id+'"><span class="step-number">'+(index+1)+'</span>'+label+' <small>'+count+'</small></button>').join('')+'</nav>'+(state.tab==='materials'?materialsPage():state.tab==='report'?reportPage():cardsPage());}
function materialCard(m,index,prefix='source'){let preview='';if(m.blob){const url=fileUrl(m.blob);if(m.mime?.startsWith('image/'))preview='<img src="'+url+'" alt="'+esc(m.title)+'">';else if(m.mime?.startsWith('video/'))preview='<video src="'+url+'" controls preload="metadata"></video>';preview+='<p><a href="'+url+'" download="'+esc(m.fileName||m.title)+'">下载原文件</a></p>';}
return '<article class="material" id="'+prefix+'-'+esc(m.id)+'"><div class="material-header"><div class="material-icon">'+icon('file')+'</div><div><h3>'+String(index+1).padStart(2,'0')+' / '+esc(m.title)+'</h3><span class="muted">'+(m.kind==='file'?'文件材料':'文字记录')+' · '+esc(m.observedAt||'观察日期未填写')+'</span></div></div><p>'+esc(m.text||'尚无文字观察记录。')+'</p><div class="source">'+(m.sourceUrl?'<a href="'+esc(m.sourceUrl)+'" target="_blank" rel="noopener noreferrer">打开来源 ↗</a>':'<span>用户补充，无公开链接</span>')+'</div><p class="muted">'+esc(m.coverage)+'</p>'+(preview?'<details><summary>查看已保存的文件</summary>'+preview+'</details>':'')+'</article>';}
function materialsPage(){const t=state.task;return '<div class="section-grid"><section><div class="section-title"><h2>本次研究的材料</h2><span class="muted">'+t.materials.length+' 份材料</span></div>'+(t.materials.length?t.materials.map((m,i)=>materialCard(m,i)).join(''):'<div class="empty"><div class="empty-icon">'+icon('file')+'</div><h3>从一份真实材料开始</h3><p>可先补充主页截图或观察记录。只有封面时，完整口播与分镜仍保持未知。</p></div>')+'<div class="notice-box neutral"><strong>当前缺口</strong><br>未自动读取主页与视频；没有完整口播、镜头时序或后台留存数据。上传文件只表示材料已保存。</div></section>'+(t.mode==='sample'?'<section class="panel"><div class="eyebrow">EVIDENCE FIRST</div><h2>为什么要保留来源？</h2><p class="subtitle">每条分析都应能回答：看到了什么，依据在哪，还有什么不知道。</p><p class="subtitle">这个样例只保留了历史观察摘要，因此不会展示虚构的逐字稿、时间戳或后台指标。</p><div class="form-actions"><button class="btn primary" data-action="tab" data-tab="report">查看拆解报告 '+icon('arrow')+'</button></div></section>':'<section class="panel"><div class="panel-title"><h2>补充一份材料</h2><span class="badge outline">自动分析未接通</span></div><form id="material"><div class="form-grid"><div class="field full"><label for="material-title">材料名称</label><input id="material-title" name="title" maxlength="120" placeholder="例如：主页截图 / 代表作品的观察"></div><div class="field full"><label for="material-source">来源链接 <span class="optional">选填</span></label><input id="material-source" name="sourceUrl" type="url" value="'+esc(t.url)+'" maxlength="1500"></div><div class="field full"><label for="material-text">我实际看到了什么 <span class="optional">文字或文件至少提供一项</span></label><textarea id="material-text" name="text" maxlength="20000" placeholder="记录实际看到的标题、画面或口播。没有取得的部分请写明。"></textarea></div><div class="field full"><label for="material-file">截图、视频或文稿 <span class="optional">单个文件不超过 50 MB</span></label><input id="material-file" name="file" type="file" accept="image/png,image/jpeg,image/webp,video/mp4,video/webm,text/plain,.md"></div><div class="field full"><label for="observedAt">观察日期 <span class="optional">未知可留空</span></label><input id="observedAt" name="observedAt" type="date"></div></div><div class="form-actions"><span class="muted">原文件只保存在当前浏览器。</span><button class="btn primary" type="submit">'+icon('plus')+' 保存材料</button></div></form></section>')+'</div>';}
function citation(m){return '<button class="citation" data-action="source" data-id="'+esc(m.id)+'">'+icon('file')+' '+esc(m.title)+'</button>';}
function reportPage(){if(state.editing)return editorPage();const t=state.task,r=currentReport();if(!r)return '<div class="empty"><div class="empty-icon">'+icon('search')+'</div><h3>材料齐一点，结论就可靠一点</h3><p>添加实际观察后，可以记录定位、选题或视觉特点。当前支持人工整理，每条结论都要选择依据。</p><button class="btn primary" data-action="edit-report" '+(!t.materials.length?'disabled':'')+'>整理拆解报告 '+icon('arrow')+'</button>'+(!t.materials.length?'<p>请先添加至少一份真实材料。</p><button class="btn" data-action="tab" data-tab="materials">去添加材料</button>':'')+'</div>';
const stale=reportStale(t,r);
return '<div class="report-toolbar"><div><select id="report-version" aria-label="报告版本">'+t.reports.map(v=>'<option value="'+v.id+'" '+(r.id===v.id?'selected':'')+'>报告 v'+v.version+' · '+(v.origin==='sample'?'历史样例':'人工整理')+'</option>').join('')+'</select> <span class="muted">依据 '+r.materials.length+' 份材料</span></div><div class="button-row"><button class="btn small" data-action="export-md">'+icon('download')+' 导出报告</button>'+(t.mode!=='sample'?'<button class="btn primary small" data-action="edit-report">整理新版本</button>':'')+'</div></div>'+(stale?'<div class="notice-box">账号背景或材料已有更新。此报告基于输入 v'+r.inputRevision+'，当前为 v'+t.revision+'；建议待更新，请整理新版本后再选题。</div>':'')+'<div class="notice-box neutral"><strong>分析覆盖范围</strong><br>'+esc(r.limitations||'依据用户提供的材料人工整理；未覆盖完整视频和后台数据。')+'</div><div class="insight-grid">'+r.insights.map((i,index)=>'<article class="insight"><div class="number">'+String(index+1).padStart(2,'0')+'</div><span class="badge '+(i.type==='inference'?'sample':'outline')+'">'+(i.type==='inference'?'推测 · 待验证':'观察记录')+'</span><h3>'+esc(i.dimension)+'</h3><p>'+esc(i.text)+'</p>'+i.sourceIds.map(id=>r.materials.find(m=>m.id===id)).filter(Boolean).map(citation).join('')+'</article>').join('')+'</div><div class="section-title"><div><div class="eyebrow">MAKE IT YOURS</div><h2>从借鉴里，找到值得做的选题</h2></div><span class="muted">'+r.ideas.length+' 个建议</span></div>'+(r.ideas.length?r.ideas.map((i,index)=>{const picked=t.cards.some(c=>c.reportId===r.id&&c.ideaId===i.id);return '<article class="idea"><span class="index">0'+(index+1)+'</span><div class="idea-content"><h3>'+esc(i.title)+'</h3><p>'+esc(i.reason)+'</p>'+i.sourceIds.map(id=>r.materials.find(m=>m.id===id)).filter(Boolean).map(citation).join('')+'</div><button class="btn '+(picked?'':'primary')+' small" data-action="pick" data-id="'+i.id+'" '+(stale?'disabled':'')+'>'+(picked?'查看内容卡':t.mode==='sample'?'试选这条':'加入候选')+' '+icon('arrow')+'</button></article>';}).join(''):'<div class="empty"><p>这份报告还没有选题建议，整理新版本时可以补充。</p></div>')+'<details class="profile-summary" id="report-sources"><summary><span>报告保存时的背景与材料</span><span class="muted">输入 v'+r.inputRevision+' ＋</span></summary><p class="muted">方向：'+esc(r.profile.direction)+'<br>能力：'+esc(r.profile.skills)+'<br>受众：'+esc(r.profile.audience)+'</p>'+r.materials.map((m,i)=>materialCard(m,i,'report-source')).join('')+'</details>';}
const dimensions=['账号定位','受众判断','选题方向','视觉表达','作品结构'];
function sourceOptions(id){return '<option value="">选择材料依据</option>'+state.task.materials.map(m=>'<option value="'+m.id+'" '+(m.id===id?'selected':'')+'>'+esc(m.title)+'</option>').join('');}
function readDraft(){const form=document.querySelector('#report-editor');if(!form)return;const data=new FormData(form);state.draft.insights=state.draft.insights.map((_,n)=>({dimension:data.get('dimension-'+n),type:data.get('type-'+n),text:data.get('insight-'+n),sourceIds:[data.get('source-'+n)].filter(Boolean)}));state.draft.ideas=state.draft.ideas.map((_,n)=>({title:data.get('idea-title-'+n),reason:data.get('idea-reason-'+n),sourceIds:[data.get('idea-source-'+n)].filter(Boolean)}));state.draft.limitations=data.get('limitations');}
function editorPage(){const d=state.draft;return '<section class="panel"><div class="panel-title"><div><h2>人工整理拆解报告</h2><p class="muted">草稿暂存在当前页面；保存后才会保留为独立报告版本。</p></div><button class="btn quiet small" data-action="cancel-editor">返回报告</button></div><form id="report-editor">'+d.insights.map((i,n)=>'<div class="editor-row"><div class="form-grid"><div class="field"><label for="dimension-'+n+'">分析维度</label><select id="dimension-'+n+'" name="dimension-'+n+'">'+dimensions.map(v=>'<option '+(v===i.dimension?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="field"><label for="type-'+n+'">判断类型</label><select id="type-'+n+'" name="type-'+n+'"><option value="observation" '+(i.type==='observation'?'selected':'')+'>观察记录</option><option value="inference" '+(i.type==='inference'?'selected':'')+'>推测 · 待验证</option></select></div><div class="field full"><label for="insight-'+n+'">结论 '+(n+1)+'</label><textarea id="insight-'+n+'" name="insight-'+n+'" maxlength="4000" placeholder="具体观察或判断">'+esc(i.text)+'</textarea></div><div class="field full"><label for="source-'+n+'">材料依据</label><select id="source-'+n+'" name="source-'+n+'">'+sourceOptions(i.sourceIds?.[0])+'</select></div></div></div>').join('')+'<div class="editor-actions"><button type="button" class="btn small" data-action="add-insight">'+icon('plus')+' 再记一条结论</button></div><div class="section-title"><h2>可以开始制作的选题</h2><span class="muted">选填</span></div>'+d.ideas.map((i,n)=>'<div class="editor-row"><div class="form-grid"><div class="field full"><label for="idea-title-'+n+'">选题标题</label><input id="idea-title-'+n+'" name="idea-title-'+n+'" value="'+esc(i.title)+'" maxlength="160" placeholder="给一个具体任务或结果起标题"></div><div class="field full"><label for="idea-reason-'+n+'">为什么适合我的方向</label><textarea id="idea-reason-'+n+'" name="idea-reason-'+n+'" maxlength="2000">'+esc(i.reason)+'</textarea></div><div class="field full"><label for="idea-source-'+n+'">借鉴来源</label><select id="idea-source-'+n+'" name="idea-source-'+n+'">'+sourceOptions(i.sourceIds?.[0])+'</select></div></div></div>').join('')+'<div class="editor-actions"><button type="button" class="btn small" data-action="add-idea">'+icon('plus')+' 再加一个选题</button></div><div class="field full"><label for="limitations">这份报告还缺什么</label><textarea id="limitations" name="limitations" maxlength="2000" placeholder="例如：只有主页截图，尚未取得完整视频口播。">'+esc(d.limitations)+'</textarea></div><div class="form-actions"><span class="muted">报告 v'+(state.task.reports.length+1)+' · 保留当前输入 v'+state.task.revision+'</span><button class="btn primary" type="submit">'+icon('check')+' 保存报告</button></div></form></section>';}
function cardsPage(){const t=state.task;if(!t.cards.length)return '<div class="empty"><div class="empty-icon">'+icon('box')+'</div><h3>保留候选，交给下一步筛选</h3><p>在拆解报告中选取候选建议，保存来源、适配理由和背景，交给后续选题模块。</p><button class="btn primary" data-action="tab" data-tab="report">去报告里选一条 '+icon('arrow')+'</button></div>';
return '<div class="section-title"><h2>候选选题交接</h2><span class="muted">仅为候选，尚未最终入选或排期</span></div>'+t.cards.map(c=>'<article class="card-detail"><span class="badge '+(c.mode==='sample'?'sample':'')+'">'+(c.mode==='sample'?'样例候选卡 · 预览':'候选 · 尚未入选或排期')+'</span><h2>'+esc(c.title)+'</h2><p>'+esc(c.reason)+'</p>'+(c.inputRevision!==t.revision?'<div class="notice-box">此卡片保留了旧版背景，请结合最新方向重新确认。</div>':'')+'<dl><dt>账号方向</dt><dd>'+esc(c.profile.direction)+'</dd><dt>借鉴来源</dt><dd>'+c.sources.map(m=>esc(m.title)).join('、')+'</dd><dt>报告版本</dt><dd>v'+c.reportVersion+' · 输入 v'+c.inputRevision+'</dd><dt>接下来准备</dt><dd>真实操作结果、关键步骤及仍缺失的素材。</dd></dl><div class="form-actions"><span class="muted">背景与来源已随卡片保存。</span><button class="btn small" data-action="export-card" data-id="'+c.id+'">'+icon('download')+' 导出内容卡</button></div></article>').join('');}
function render(){
blobs.forEach(URL.revokeObjectURL);blobs=[];const t=state.task;
app.innerHTML='<div class="shell"><aside class="sidebar"><button class="brand" data-action="new" aria-label="月老工作台首页"><span class="brand-icon">◔</span><span>月老<small>创作工作台</small></span></button><div class="side-workspace"><span class="workspace-avatar">月</span><span>我的工作空间<small>个人创作</small></span></div><div><div class="side-label">开始创作</div><nav aria-label="主导航"><button class="nav-btn '+(!t?'active':'')+'" data-action="new">'+icon('plus')+' 新建对标研究</button><button class="nav-btn '+(t?.mode==='sample'?'active':'')+'" data-action="sample">'+icon('search')+' 看一份拆解样例</button></nav></div><button class="history-toggle" data-action="toggle-history" aria-expanded="false" aria-controls="research-history">我的研究 <span>展开 ⌄</span></button><div class="history" id="research-history"><div class="side-label">我的研究 <span>'+state.tasks.filter(x=>x.mode!=='sample').length+'</span></div>'+state.tasks.filter(x=>x.mode!=='sample').map(x=>'<button class="nav-btn history-item '+(x.id===t?.id?'active':'')+'" data-action="open" data-id="'+x.id+'">'+icon('file')+'<span>'+esc(x.title)+'<small>'+x.materials.length+' 份材料 · '+x.reports.length+' 份报告</small></span></button>').join('')+'</div><div class="side-note"><span class="note-symbol">↗</span><strong>灵感有出处，<br>内容有自己的方向。</strong><span>对标研究 · 本地原型 v0.2</span></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span>工作空间</span><span>/</span><strong>对标账号拆解</strong></div><span class="save-status"><span class="dot"></span>当前浏览器保存</span></header><div class="content '+(!t?'home-content':'research-content')+'">'+(state.storageError?'<div class="notice-box">'+esc(state.storageError)+'</div>':'')+(t?taskPage():newPage())+'<div class="footer-note"><span>月老 · 创作工作台</span><span>从理解开始，一步一步做成作品。</span></div></div></main></div>';
}
function download(data,name,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function rememberDraft(){if(state.editing&&state.task){readDraft();state.drafts.set(state.task.id,copy(state.draft));}}
function startEditor(){const r=currentReport();state.draft=state.drafts.has(state.task.id)?copy(state.drafts.get(state.task.id)):r?{insights:copy(r.insights),ideas:copy(r.ideas),limitations:r.limitations}:{insights:[{dimension:'账号定位',type:'observation',text:'',sourceIds:[]}],ideas:[{title:'',reason:'',sourceIds:[]}],limitations:'仅依据当前材料人工整理，尚未取得完整视频和后台数据。'};state.editing=true;render();}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;try{switch(b.dataset.action){
case 'toggle-history':{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.querySelector('span').textContent=open?'收起 ⌃':'展开 ⌄';document.querySelector('#research-history').classList.toggle('is-open',open);break;}
case 'new':navigate();break;
case 'sample':navigate('sample');break;
case 'open':navigate(b.dataset.id);break;
case 'tab':rememberDraft();state.tab=b.dataset.tab;state.editing=false;render();break;
case 'source':{const group=document.querySelector('#report-sources');if(group){group.open=true;const el=document.getElementById('report-source-'+b.dataset.id);el?.scrollIntoView({block:'center'});el?.classList.add('source-focus');}break;}
case 'edit-report':startEditor();break;
case 'cancel-editor':rememberDraft();state.editing=false;render();break;
case 'add-insight':readDraft();state.draft.insights.push({dimension:'选题方向',type:'observation',text:'',sourceIds:[]});render();break;
case 'add-idea':readDraft();state.draft.ideas.push({title:'',reason:'',sourceIds:[]});render();break;
case 'pick':{busy=true;await store(selectIdea(state.task,currentReport().id,b.dataset.id));state.tab='cards';render();toast(state.task.mode==='sample'?'已保存样例候选卡':'候选交接卡已保存');break;}
case 'export-json':download(exportTask(state.task),'对标研究-'+state.task.id+'.json');toast('已导出文字与来源；附件原文件不包含在内。');break;
case 'export-md':download(markdownReport(state.task,currentReport()),'拆解报告-v'+currentReport().version+'.md','text/markdown;charset=utf-8');break;
case 'export-card':{download(exportCandidate(state.task,b.dataset.id),'内容卡-'+b.dataset.id+'.json');break;}
}}catch(error){toast(error.message,true);}finally{busy=false;}});
app.addEventListener('input',e=>{if(e.target.closest('#report-editor'))rememberDraft();});
app.addEventListener('change',e=>{if(e.target.closest('#report-editor'))rememberDraft();if(e.target.id==='report-version'){state.reportId=e.target.value;render();}});
app.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const form=e.target,data=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');busy=true;if(submit)submit.disabled=true;
try{
if(form.id==='new-task'){const task=createTask(data);await store(task);navigate(task.id);toast('研究任务已保存，可以开始补充材料。');}
if(form.id==='profile'){await store(updateProfile(state.task,data));render();toast('账号背景已保存。');}
if(form.id==='material'){const file=data.file?.size?data.file:null;if(file && !(/^(image\/(png|jpeg|webp)|video\/(mp4|webm)|text\/plain)$/.test(file.type)||/\.(txt|md)$/i.test(file.name)))throw new Error('请选择 PNG、JPG、WebP、MP4、WebM 或文本文件。');await store(addMaterial(state.task,{...data,title:data.title||file?.name,blob:file,fileName:file?.name}));render();toast('材料已保存，尚未自动分析内容。');}
if(form.id==='report-editor'){readDraft();const d=state.draft;await store(saveReport(state.task,{insights:d.insights.filter(i=>i.text?.trim()),ideas:d.ideas.filter(i=>i.title?.trim()||i.reason?.trim()),limitations:d.limitations}));state.drafts.delete(state.task.id);state.draft=null;state.editing=false;state.reportId=null;render();toast('报告已保存，来源和背景已随版本保留。');}
}catch(error){toast(error.message,true);}finally{busy=false;if(submit)submit.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(state.drafts.size){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',route);
app.innerHTML='<div class="loading">正在打开你的研究工作台…</div>';
try{state.tasks=await listTasks();}catch(e){state.storageError=e.message;}
route();
